const P = [
  { id: '691331356a3b9a68428ab3.43540470', name: 'Chat AI - frontend' },
  { id: '225008626a33e62b328c63.04676982', name: 'Chat AI (emails)' }
];
const out = [];
for (const p of P) {
  for (let page = 1; page <= 3; page++) {
    out.push({ json: { project_id: p.id, project_name: p.name, page: page } });
  }
}
return out;

const SINCE = 1787443200;
const meta = $('Projects').all();
const rows = $input.all();
const byProject = {};
for (let i = 0; i < rows.length; i++) {
  const pi = rows[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const m = (meta[idx] || meta[i] || {}).json || {};
  const r = rows[i].json || {};
  const keys = (r.body && r.body.keys) ? r.body.keys : [];
  if (!byProject[m.project_name]) { byProject[m.project_name] = { seen: 0, recent: [] }; }
  const b = byProject[m.project_name];
  b.seen += keys.length;
  for (const k of keys) {
    if (!k.created_at_timestamp || k.created_at_timestamp < SINCE) { continue; }
    const kn = k.key_name;
    b.recent.push({
      name: (typeof kn === 'string') ? kn : ((kn && (kn.web || kn.other)) || ''),
      created: k.created_at,
      tags: k.tags || [],
      description: k.description || '',
      screenshots: (k.screenshots || []).map(function (s) { return s.title; })
    });
  }
}
const out = [];
for (const name of Object.keys(byProject)) {
  const b = byProject[name];
  out.push({ json: { project: name, keys_seen: b.seen, recent_count: b.recent.length, recent: b.recent } });
}
return out;
